###################################
#           QUESTION 1            #
###################################

def partie_entiere(flottant):
    return int(flottant)

def permuter(tab, ind1, ind2):
    temp = tab[ind2]
    tab[ind2] = tab[ind1]
    tab[ind1] = temp

# Code à surveiller
def tri_dobosiewicz(tab):
    start_time = time.time()
    n= len(tab)
    intv = n
    fini = False
    while (intv > 1 or not(fini)):
        intv = partie_entiere(intv/1.3)

        if (intv < 1):
            intv = 1

        i = 0
        fini = True

        while (i + intv < n):
            if (tab[i]>tab[i+intv]):
                permuter(tab, i, i+intv)
                fini = False
            
            i += 1
#fin
    end_time = time.time()

    elapsed_time = end_time - start_time
    print(f"Temps écoulé : {elapsed_time} secondes")

    return tab

